BEGIN;
CREATE TABLE kurikulum (id BIGSERIAL PRIMARY KEY, kode VARCHAR(50) NOT NULL UNIQUE, nama VARCHAR(255) NOT NULL, tahun_mulai SMALLINT NOT NULL, tahun_selesai SMALLINT, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (status IN ('draft','aktif','nonaktif')));
CREATE TABLE mata_kuliah (id BIGSERIAL PRIMARY KEY, kode VARCHAR(50) NOT NULL UNIQUE, nama VARCHAR(255) NOT NULL, sks SMALLINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'aktif', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (sks BETWEEN 1 AND 12), CHECK (status IN ('aktif','nonaktif')));
CREATE TABLE konsentrasi (id BIGSERIAL PRIMARY KEY, kode VARCHAR(50) NOT NULL UNIQUE, nama VARCHAR(255) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'aktif', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (status IN ('aktif','nonaktif')));
CREATE TABLE kurikulum_mata_kuliah (id BIGSERIAL PRIMARY KEY, kurikulum_id BIGINT NOT NULL REFERENCES kurikulum(id) ON DELETE CASCADE, mata_kuliah_id BIGINT NOT NULL REFERENCES mata_kuliah(id) ON DELETE RESTRICT, semester_rekomendasi SMALLINT, sifat VARCHAR(20) NOT NULL DEFAULT 'wajib', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (kurikulum_id,mata_kuliah_id), CHECK (semester_rekomendasi IS NULL OR semester_rekomendasi BETWEEN 1 AND 14), CHECK (sifat IN ('wajib','pilihan')));
CREATE TABLE konsentrasi_mata_kuliah (konsentrasi_id BIGINT NOT NULL REFERENCES konsentrasi(id) ON DELETE CASCADE, kurikulum_mata_kuliah_id BIGINT NOT NULL REFERENCES kurikulum_mata_kuliah(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (konsentrasi_id,kurikulum_mata_kuliah_id));
CREATE TABLE mata_kuliah_prasyarat (id BIGSERIAL PRIMARY KEY, kurikulum_id BIGINT NOT NULL REFERENCES kurikulum(id) ON DELETE CASCADE, mata_kuliah_id BIGINT NOT NULL REFERENCES mata_kuliah(id) ON DELETE CASCADE, prasyarat_mata_kuliah_id BIGINT NOT NULL REFERENCES mata_kuliah(id) ON DELETE RESTRICT, nilai_minimum CHAR(1) NOT NULL DEFAULT 'D', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (kurikulum_id,mata_kuliah_id,prasyarat_mata_kuliah_id), CHECK (mata_kuliah_id <> prasyarat_mata_kuliah_id), CHECK (nilai_minimum IN ('A','B','C','D','E')));
CREATE TABLE periode_akademik (id BIGSERIAL PRIMARY KEY, kode VARCHAR(30) NOT NULL UNIQUE, tahun_ajaran_mulai SMALLINT NOT NULL, jenis_semester VARCHAR(20) NOT NULL, tanggal_mulai DATE NOT NULL, tanggal_selesai DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'direncanakan', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (tahun_ajaran_mulai,jenis_semester), CHECK (jenis_semester IN ('ganjil','genap','antara')), CHECK (tanggal_selesai >= tanggal_mulai));
CREATE TABLE academic_imports (id BIGSERIAL PRIMARY KEY, mahasiswa_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_document_id BIGINT NOT NULL REFERENCES dokumen_mahasiswa(id) ON DELETE RESTRICT, periode_akademik_id BIGINT REFERENCES periode_akademik(id) ON DELETE RESTRICT, import_type VARCHAR(20) NOT NULL, idempotency_key VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'pending', attempt_count INTEGER NOT NULL DEFAULT 0, raw_result JSONB, error_message TEXT, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (import_type IN ('krs','khs','transkrip')), CHECK (status IN ('pending','processing','succeeded','failed')));
CREATE TABLE pengambilan_mata_kuliah (id BIGSERIAL PRIMARY KEY, mahasiswa_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mata_kuliah_id BIGINT NOT NULL REFERENCES mata_kuliah(id) ON DELETE RESTRICT, periode_akademik_id BIGINT NOT NULL REFERENCES periode_akademik(id) ON DELETE RESTRICT, academic_import_id BIGINT REFERENCES academic_imports(id) ON DELETE SET NULL, source_document_id BIGINT REFERENCES dokumen_mahasiswa(id) ON DELETE RESTRICT, attempt SMALLINT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'diambil', nilai_angka NUMERIC(5,2), nilai_huruf CHAR(1), bobot_nilai NUMERIC(3,2), raw_result JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (mahasiswa_user_id,mata_kuliah_id,periode_akademik_id,attempt), CHECK (attempt >= 1), CHECK (status IN ('direncanakan','diambil','selesai','dibatalkan')), CHECK (nilai_angka IS NULL OR nilai_angka BETWEEN 0 AND 100), CHECK (nilai_huruf IS NULL OR nilai_huruf IN ('A','B','C','D','E')), CHECK (bobot_nilai IS NULL OR bobot_nilai BETWEEN 0 AND 4));
CREATE INDEX idx_academic_imports_mahasiswa_created ON academic_imports (mahasiswa_user_id,created_at DESC);
CREATE INDEX idx_pengambilan_mahasiswa_periode ON pengambilan_mata_kuliah (mahasiswa_user_id,periode_akademik_id);
CREATE VIEW v_nilai_efektif AS SELECT ranked.*, ranked.nilai_huruf IN ('A','B','C') AS lulus, ranked.nilai_huruf IN ('D','E') AS perlu_perhatian FROM (SELECT p.id AS pengambilan_id,p.mahasiswa_user_id,p.mata_kuliah_id,mk.kode AS kode_mata_kuliah,mk.nama AS nama_mata_kuliah,mk.sks,p.periode_akademik_id,pa.kode AS kode_periode,p.attempt,p.nilai_angka,p.nilai_huruf,COALESCE(p.bobot_nilai,CASE p.nilai_huruf WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 WHEN 'E' THEN 0 END)::NUMERIC(3,2) AS bobot_efektif,p.source_document_id,p.academic_import_id,ROW_NUMBER() OVER (PARTITION BY p.mahasiswa_user_id,p.mata_kuliah_id ORDER BY p.bobot_nilai DESC NULLS LAST,p.nilai_angka DESC NULLS LAST,pa.tanggal_selesai DESC,p.attempt DESC,p.id DESC) AS nilai_rank FROM pengambilan_mata_kuliah p JOIN mata_kuliah mk ON mk.id=p.mata_kuliah_id JOIN periode_akademik pa ON pa.id=p.periode_akademik_id WHERE p.status='selesai' AND p.nilai_huruf IS NOT NULL) ranked WHERE ranked.nilai_rank=1;
CREATE VIEW v_ringkasan_akademik AS SELECT mahasiswa_user_id,COUNT(*) AS total_mata_kuliah_dinilai,COUNT(*) FILTER (WHERE nilai_huruf='A') AS jumlah_a,COUNT(*) FILTER (WHERE nilai_huruf='B') AS jumlah_b,COUNT(*) FILTER (WHERE nilai_huruf='C') AS jumlah_c,COUNT(*) FILTER (WHERE nilai_huruf='D') AS jumlah_d,COUNT(*) FILTER (WHERE nilai_huruf='E') AS jumlah_e,COUNT(*) FILTER (WHERE perlu_perhatian) AS jumlah_d_e,COALESCE(SUM(sks) FILTER (WHERE lulus),0) AS sks_lulus,COALESCE(SUM(sks) FILTER (WHERE perlu_perhatian),0) AS sks_d_e,ROUND(SUM(bobot_efektif*sks)/NULLIF(SUM(sks),0),2) AS ipk_efektif FROM v_nilai_efektif GROUP BY mahasiswa_user_id;
COMMIT;
